<?php $success=sessionSuccess();$error=sessionError();$errors=sessionErrors(); ?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student - DormSync</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}main{max-width:900px;margin:auto;padding:36px 24px}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:22px;margin-bottom:20px}label{display:block;font-size:13px;font-weight:600;margin:12px 0 6px}input,select,textarea,button{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}textarea{min-height:80px}button{margin-top:16px;background:#2563eb;color:#fff;border-color:#2563eb;font-weight:600}.message{padding:10px;background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.item{border-bottom:1px solid #e7ebf2;padding:10px 0}.muted{color:#718096}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><header class="topbar"><a href="/warden/students">Back to students</a></header><main><h1><?=htmlspecialchars($student['full_name'])?></h1><?php if($success):?><p class="message"><?=htmlspecialchars($success)?></p><?php endif;?><?php if($error):?><p class="message error"><?=htmlspecialchars($error)?></p><?php endif;?><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $item):?><p class="message error"><?=htmlspecialchars($item)?></p><?php endforeach;endforeach;?><section class="panel"><form method="post" action="/warden/student-update/<?= (int)$student['id'] ?>"><div class="grid"><div><label>Full name</label><input name="full_name" value="<?=htmlspecialchars($student['full_name'])?>" required></div><div><label>Phone</label><input name="phone" value="<?=htmlspecialchars($student['phone']??'')?>"></div><div><label>Parent contact</label><input name="parent_contact" value="<?=htmlspecialchars($student['parent_contact']??'')?>"></div><div><label>Emergency contact</label><input name="emergency_contact" value="<?=htmlspecialchars($student['emergency_contact']??'')?>"></div></div><label>Address</label><textarea name="address"><?=htmlspecialchars($student['address']??'')?></textarea><label>Room</label><select name="room_id"><option value="">Not assigned</option><?php foreach($rooms as $room):?><option value="<?= (int)$room['id']?>" <?=$student['room_id']==$room['id']?'selected':''?>><?=htmlspecialchars($room['room_number'].' / '.$room['block'])?></option><?php endforeach;?></select><button type="submit">Save student</button></form></section><section class="panel"><h2>Current information</h2><div class="item">Student ID: <?=htmlspecialchars($student['student_id'])?></div><div class="item">Email: <?=htmlspecialchars($student['email'])?></div><div class="item">Room: <?=htmlspecialchars($student['room_number']??'Not assigned')?></div></section><section class="panel"><h2>Complaints</h2><?php foreach($complaints as $item):?><div class="item"><?=htmlspecialchars($item['subject'])?> <span class="muted">(<?=htmlspecialchars($item['status'])?>)</span></div><?php endforeach;?></section><section class="panel"><h2>Fees</h2><?php foreach($fees as $item):?><div class="item">₹<?=number_format((float)$item['amount'],2)?> - <?=htmlspecialchars($item['status'])?></div><?php endforeach;?></section><section class="panel"><h2>Visitors</h2><?php foreach($visitors as $item):?><div class="item"><?=htmlspecialchars($item['visitor_name'])?> - <?=htmlspecialchars($item['status'])?></div><?php endforeach;?></section></main></body></html>
